package com.airesumebuilder.feature.admin.repository;import com.airesumebuilder.common.exception.ResourceNotFoundException;import com.airesumebuilder.feature.admin.service.AdminService.*;import java.sql.*;import java.time.Instant;import java.util.List;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;
@Repository public class AdminRepository{private final JdbcTemplate jdbc;public AdminRepository(JdbcTemplate j){jdbc=j;}public List<UserView>users(int limit,int offset){return jdbc.query("SELECT id,first_name,last_name,email,role,status,created_at FROM users WHERE deleted_at IS NULL ORDER BY created_at DESC LIMIT ? OFFSET ?",this::user,limit,offset);}public long userCount(){Long n=jdbc.queryForObject("SELECT COUNT(*) FROM users WHERE deleted_at IS NULL",Long.class);return n==null?0:n;}public UserView update(String adminEmail,long id,String field,String value,String action){String column=field.equals("role")?"role":"status";if(jdbc.update("UPDATE users SET "+column+"=?,updated_at=NOW(6) WHERE id=? AND deleted_at IS NULL",value,id)==0)throw new ResourceNotFoundException("User not found.");jdbc.update("INSERT INTO admin_action_logs(admin_user_id,target_user_id,action,details,created_at) SELECT id,?,?,JSON_OBJECT(?,?),NOW(6) FROM users WHERE email=?",id,action,column,value,adminEmail);return get(id);}public UserView get(long id){return jdbc.query("SELECT id,first_name,last_name,email,role,status,created_at FROM users WHERE id=? AND deleted_at IS NULL",this::user,id).stream().findFirst().orElseThrow(()->new ResourceNotFoundException("User not found."));}public String email(long id){return get(id).email();}public List<ActionView>actions(int limit,int offset){return jdbc.query("SELECT l.id,l.admin_user_id,l.target_user_id,l.action,l.details,l.created_at FROM admin_action_logs l ORDER BY l.created_at DESC LIMIT ? OFFSET ?",(r,n)->new ActionView(r.getLong(1),r.getLong(2),(Long)r.getObject(3),r.getString(4),r.getString(5),r.getTimestamp(6).toInstant()),limit,offset);}private UserView user(ResultSet r,int n)throws SQLException{return new UserView(r.getLong("id"),r.getString("first_name"),r.getString("last_name"),r.getString("email"),r.getString("role"),r.getString("status"),r.getTimestamp("created_at").toInstant());}}
